using System.Text.RegularExpressions;

namespace Blog.Domain;

/// <summary>
/// SHA-256 of the original file, as lowercase hexadecimal. It identifies an uploaded file (same content = same asset)
/// and ends up as a folder on disk, so validating it guarantees nothing is written outside /media.
/// </summary>
internal static partial class ContentHash
{
    public const int Length = 64;

    // Generated by the server, never typed by a user: an invalid value is a programming error.
    [GeneratedRegex("^[0-9a-f]{64}$")]
    private static partial Regex Pattern();

    public static void EnsureValid(string hash)
    {
        if (!Pattern().IsMatch(hash))
        {
            throw new ArgumentException("The hash must be a lowercase hexadecimal SHA-256.", nameof(hash));
        }
    }
}
